import { useState } from 'react';
import {
  Screen,
  Card,
  Stack,
  Row,
  TextField,
  Button,
  Badge,
  Alert,
  KeyBar,
} from '@nexti/ds';

// Assumptions to confirm at gate C2 (the spec defines no navigation_out or error texts):
// - Option 1 (Pagar una orden) opens SCR-PAGOORD.
// - Option 2 (Consultar una orden) opens SCR-PAGORES.
// - The MENSAJE texts for the empty and invalid option cases are proposed here.
// - PF3 (Salir) has no target screen, so it is simulated with local state.

type Msg = { tone: 'info' | 'success' | 'warning' | 'error'; text: string } | null;

export default function PagoMenu({ navigate }: { navigate: (to: string) => void }) {
  const [opcion, setOpcion] = useState('');
  const [message, setMessage] = useState<Msg>(null);
  const [exited, setExited] = useState(false);

  const fecha = '15/03/25'; // FECHA, format 99/99/99

  const readValue = (v: any): string =>
    typeof v === 'string' ? v : v?.target?.value ?? '';

  const handleChange = (v: any) => {
    const digits = readValue(v).replace(/\D/g, '').slice(0, 1);
    setOpcion(digits);
    if (message) setMessage(null);
  };

  const error =
    message?.tone === 'error' || message?.tone === 'warning' ? message.text : undefined;

  const submit = (value: string = opcion) => {
    if (value === '') {
      setMessage({ tone: 'error', text: 'Ingrese una opción para continuar.' });
      return;
    }
    if (value === '1') {
      setMessage({ tone: 'success', text: 'Abriendo pago de órdenes…' });
      navigate('SCR-PAGOORD');
      return;
    }
    if (value === '2') {
      setMessage({ tone: 'success', text: 'Abriendo consulta de orden…' });
      navigate('SCR-PAGORES');
      return;
    }
    setMessage({ tone: 'error', text: 'Opción inválida. Ingrese 1 o 2.' });
  };

  const exit = () => {
    setExited(true);
    setMessage(null);
  };

  const pick = (value: string) => {
    setOpcion(value);
    setMessage(null);
  };

  const keys = (
    <KeyBar
      actions={[
        { key: 'ENTER', label: 'Continuar', onPress: () => submit(), primary: true },
        { key: 'PF3', label: 'Salir', onPress: exit },
      ]}
    />
  );

  if (exited) {
    return (
      <Screen title="Banco ficticio - Pagos" code="PAGOMEN" keys={keys}>
        <Stack>
          <Alert tone="info">Sesión finalizada. Ha salido del menú de pagos.</Alert>
          <Row>
            <Button variant="secondary" onClick={() => setExited(false)}>
              Volver al menú
            </Button>
          </Row>
        </Stack>
      </Screen>
    );
  }

  return (
    <Screen title="Banco ficticio - Pagos" code="PAGOMEN" keys={keys}>
      <div
        onKeyDown={(e) => {
          if (e.key === 'Enter') {
            e.preventDefault();
            submit();
          } else if (e.key === 'F3') {
            e.preventDefault();
            exit();
          }
        }}
      >
        <Stack>
          <Row>
            <span>Fecha:</span>
            <span data-field="FECHA">
              <Badge>{fecha}</Badge>
            </span>
          </Row>

          <Card title="Menú de pagos">
            <Stack>
              <Row>
                <Button
                  variant={opcion === '1' ? 'primary' : 'secondary'}
                  onClick={() => pick('1')}
                >
                  1. Pagar una orden
                </Button>
                <Button
                  variant={opcion === '2' ? 'primary' : 'secondary'}
                  onClick={() => pick('2')}
                >
                  2. Consultar una orden
                </Button>
              </Row>

              <div data-field="OPCION">
                <TextField
                  label="Opción"
                  required
                  numeric
                  maxLength={1}
                  hint="Ingrese 1 para pagar una orden o 2 para consultar una orden"
                  error={error}
                  value={opcion}
                  onChange={handleChange}
                />
              </div>
            </Stack>
          </Card>

          <div data-field="MENSAJE" aria-live="polite">
            {message ? (
              <Alert tone={message.tone}>{message.text}</Alert>
            ) : (
              <Alert tone="info">Seleccione una opción y presione Enter para continuar.</Alert>
            )}
          </div>

          <Row>
            <Button variant="primary" shortcut="ENTER" onClick={() => submit()}>
              Continuar
            </Button>
            <Button variant="ghost" shortcut="PF3" onClick={exit}>
              Salir
            </Button>
          </Row>
        </Stack>
      </div>
    </Screen>
  );
}
