import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core'
import { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms'
import { NAVIGATE } from '../app/tokens'

@Component({
  selector: 'app-pagomen-screen',
  standalone: true,
  imports: [ReactiveFormsModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <main class="nx-root nx-screen" aria-label="PAGOMEN - Banco ficticio - Pagos">
      <header class="nx-screen__header">
        <h1 class="nx-screen__title">BANCO FICTICIO - PAGOS</h1>
      </header>

      <form class="nx-screen__body" [formGroup]="form" (ngSubmit)="submit()" novalidate>
        <div class="nx-card">
          <div class="nx-field" data-field="FECHA">
            <span class="nx-field__label">FECHA</span>
            <p>{{ fecha }}</p>
          </div>
        </div>

        <div class="nx-card">
          <div class="nx-field" data-field="OPCION">
            <label class="nx-field__label" for="opcion">OPCION</label>
            <input
              id="opcion"
              class="nx-input"
              type="text"
              formControlName="OPCION"
              maxlength="1"
              inputmode="numeric"
              autocomplete="off"
              required
            />
            <p>1. Pagar una orden &nbsp; 2. Consultar una orden</p>
            @if (opcionError()) {
              <p class="nx-field__error" role="alert">{{ opcionError() }}</p>
            }
          </div>
        </div>

        <div class="nx-field" data-field="MENSAJE" aria-live="polite">
          <span class="nx-field__label">MENSAJE</span>
          @if (message()) {
            <div class="nx-alert nx-alert--error">
              <p>{{ message() }}</p>
            </div>
          } @else {
            <p></p>
          }
        </div>

        <div>
          <button type="submit" class="nx-button nx-button--primary" data-action="ENTER">CONTINUAR</button>
          <button type="button" class="nx-button nx-button--secondary" data-action="PF3" (click)="exit()">SALIR</button>
        </div>
      </form>
    </main>
  `,
})
export class PagomenScreen {
  private readonly navigate = inject(NAVIGATE)

  readonly form = new FormGroup({
    OPCION: new FormControl<string>('', { nonNullable: true, validators: [Validators.required] }),
  })

  readonly fecha = PagomenScreen.today()
  readonly opcionError = signal('')
  readonly message = signal('')

  private static today(): string {
    const d = new Date()
    const p = (n: number): string => String(n).padStart(2, '0')
    return `${p(d.getDate())}/${p(d.getMonth() + 1)}/${p(d.getFullYear() % 100)}`
  }

  submit(): void {
    this.message.set('')
    const value = this.form.controls.OPCION.value.trim()
    if (value === '') {
      this.opcionError.set('Ingrese una opción para continuar.')
      return
    }
    this.opcionError.set('')
    if (value === '1') {
      this.navigate('SCR-PAGOORD')
    } else if (value === '2') {
      this.navigate('SCR-PAGORES')
    } else {
      this.message.set('Opción inválida. Ingrese 1 o 2.')
    }
  }

  exit(): void {
    this.opcionError.set('')
    this.message.set('Sesión finalizada. Ha salido del menú de pagos.')
  }
}
